ode at (0, 0) {\includegraphics[width=6cm]{imgs/plot_statistics/mae_ce.pdf}}; 
ode at (6.25, 0) {\includegraphics[width=6cm]{imgs/plot_statistics/dosage_comparison_loss.pdf}}; \draw[thick] (-3,-2.8) -- (9.5,-2.8); 
ode at (0, -5.5) {\includegraphics[width=6cm]{imgs/plot_statistics/mae_sigma.pdf}}; 
ode at (6.25, -5.5) {\includegraphics[width=6cm]{imgs/plot_statistics/sigma_comparison_loss.pdf}}; \end{tikzpicture}} \caption{ Statistical evaluation of contrast-enhancing regions (top) and non-enhancing regions (bottom). The histograms on the left compare the considered loss functions in both regions. While the top histogram shows the mean absolute error in the contrast signal, the bottom histogram visualizes the mean absolute error of the estimated standard deviations. The proposed noise preserving loss~$\ell_{NP}$ has smaller densities at low errors in both metrics. The violin plots on the right illustrate how well the statistics within the CE region and non-CE regions overlap with the ground truth (GT). Comparing the different colored areas, we see that our distance function leads to the best overlap in both regions.}  \end{figure}
